// heal: k-sample agreement over 2 independent reads of one node
const FIELDS = ["orders"];
const norm = v => Array.isArray(v) ? v.map(norm).map(x => JSON.stringify(x)).sort() : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).sort().map(k => [k, norm(v[k])])) : v;
const key = o => JSON.stringify(norm(FIELDS.length ? Object.fromEntries(FIELDS.map(f => [f, o?.[f]])) : o));
export default function main(input) {
  const reads = ["a","b"].map(n => input[n]);
  const groups = new Map();
  for (const r of reads) { const k = key(r); const g = groups.get(k) ?? { n: 0, v: r }; g.n++; groups.set(k, g); }
  const best = [...groups.values()].sort((a, b) => b.n - a.n)[0];
  const disagreements = FIELDS.length ? FIELDS.filter(f => new Set(reads.map(r => JSON.stringify(norm(r?.[f])))).size > 1) : (groups.size > 1 ? ['*'] : []);
  return { agreed: best.n >= 2, unanimous: groups.size === 1, value: best.v, disagreements };
}

// Split the export into batches of whole lines; each line is one row whose id is its first integer.
export default function main(input) {
  const lines = String(input.export || '').split(/\r?\n/).map(s => s.trim()).filter(s => s.length > 0);
  const items = lines.map(line => {
    const m = line.match(/\d+/);
    return { id: m ? parseInt(m[0], 10) : null, line };
  });
  const SIZE = 16;
  const batches = [];
  for (let i = 0; i < items.length; i += SIZE) {
    const chunk = items.slice(i, i + SIZE);
    batches.push({
      ids: chunk.map(c => c.id),
      lines: chunk.map(c => c.line).join('\n'),
      notes: String(input.source_notes || ''),
      spec: String(input.spec || ''),
    });
  }
  return { batches, ids: items.map(c => c.id), spec: String(input.spec || '') };
}

// Deterministic master-list assembly: phone normalisation, identity linking, conflict order,
// name rules (nicknames, accent restoration), balance conversion. Parameters come from the spec text.
const FALLBACK_CALLING = {
  US: ['1', null], CA: ['1', null], GB: ['44', '0'], IE: ['353', '0'], AU: ['61', '0'], DE: ['49', '0'],
  AT: ['43', '0'], CH: ['41', '0'], FR: ['33', '0'], BE: ['32', '0'], ES: ['34', null], MX: ['52', null],
  IT: ['39', null], NL: ['31', '0'], JP: ['81', '0'], SE: ['46', '0'], DK: ['45', null], NO: ['47', null],
};

function parseSpec(spec) {
  const calling = {};
  for (const line of spec.split('\n')) {
    const m = line.match(/\b([A-Z]{2})\s+\+(\d{1,4})\s+trunk prefix:\s*(.*)$/);
    if (m) calling[m[1]] = { cc: m[2], trunk: /^0\b/.test(m[3].trim()) ? '0' : null };
  }
  if (Object.keys(calling).length === 0) {
    for (const k of Object.keys(FALLBACK_CALLING)) calling[k] = { cc: FALLBACK_CALLING[k][0], trunk: FALLBACK_CALLING[k][1] };
  }
  const rates = {};
  for (const m of spec.matchAll(/\b([A-Z]{3})\/([A-Z]{3})\s+(\d+(?:\.\d+)?)/g)) rates[m[1] + '/' + m[2]] = m[3];
  const nick = {};
  const idx = spec.search(/Appendix/i);
  const app = idx >= 0 ? spec.slice(idx) : '';
  for (const part of app.split(/[;\n]/)) {
    const m = part.match(/^\s*([^=]+?)\s*=\s*([^=]+?)\s*$/);
    if (!m) continue;
    for (const nk of m[1].split('/')) nick[nk.trim().toLowerCase()] = m[2].trim();
  }
  return { calling, rates, nick };
}

function strip(s) { return String(s || '').replace(/[\s'’`.]/g, ''); }
const NONASCII = /[^\x00-\x7f]/;
const ACC = { 'ä': ['a', 'ae'], 'ö': ['o', 'oe'], 'ü': ['u', 'ue'], 'ß': ['ss'], 'ø': ['o', 'oe'], 'å': ['a', 'aa'], 'æ': ['ae'], 'ō': ['o', 'ou'], 'ū': ['u', 'uu'] };

// ASCII renderings (lower case) of a name part; an accented letter may stand for any of its renderings.
function variants(s) {
  let out = [''];
  for (const ch of strip(s).toLowerCase()) {
    let opts;
    if (ACC[ch]) opts = ACC[ch];
    else if (NONASCII.test(ch)) opts = [ch.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^\x00-\x7f]/g, '') || ch];
    else opts = [ch];
    const next = [];
    for (const p of out) for (const o of opts) next.push(p + o);
    out = next.slice(0, 256);
  }
  return out;
}

function dl(a, b) { // Damerau (optimal string alignment) distance
  const n = a.length, m = b.length;
  const d = [];
  for (let i = 0; i <= n; i++) { d.push(new Array(m + 1).fill(0)); d[i][0] = i; }
  for (let j = 0; j <= m; j++) d[0][j] = j;
  for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++) {
    const c = a[i - 1] === b[j - 1] ? 0 : 1;
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + c);
    if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
  }
  return d[n][m];
}

function partDist(x, y) {
  let best = Infinity;
  for (const vx of variants(x)) for (const vy of variants(y)) {
    best = Math.min(best, dl(vx, vy));
    if (best === 0) return 0;
  }
  return best;
}

function formalGiven(given, NICK) {
  const k = strip(given).toLowerCase();
  return NICK[k] !== undefined ? NICK[k] : strip(given);
}

// Exact decimal arithmetic on BigInt fractions.
function dec(str) {
  let s = String(str).trim();
  if (/e/i.test(s)) s = Number(s).toFixed(12);
  let neg = false;
  if (s[0] === '-') { neg = true; s = s.slice(1); } else if (s[0] === '+') s = s.slice(1);
  const parts = s.split('.');
  const frac = parts[1] || '';
  const n = BigInt((parts[0] || '0') + frac) * (neg ? -1n : 1n);
  return { n, d: 10n ** BigInt(frac.length) };
}
function roundCents(f) {
  let n = f.n; const neg = n < 0n; if (neg) n = -n;
  const q = (2n * n * 100n + f.d) / (2n * f.d);
  const v = Number(q) / 100;
  return neg && v !== 0 ? -v : v;
}

function normPhone(raw, country, system, calling) {
  if (raw === null || raw === undefined) return null;
  let t = String(raw).trim();
  if (!t || /^(n\/a|—|-+|tbd|\?)$/i.test(t)) return null;
  let intl = false;
  if (t[0] === '+') { intl = true; t = t.slice(1); }
  else if (t.startsWith('00')) { intl = true; t = t.slice(2); }
  else if (system === 'BRIGHTDESK' && t.startsWith('011')) { intl = true; t = t.slice(3); }
  t = t.replace(/\(0\)/g, '');
  let digits = t.replace(/\D/g, '');
  if (!digits || /^0+$/.test(digits)) return null;
  if (intl) return '+' + digits;
  if (!country || !calling[country]) return null;
  const info = calling[country];
  if (info.trunk === '0' && digits[0] === '0') digits = digits.slice(1);
  if (info.cc === '1' && digits.length === 11 && digits[0] === '1') digits = digits.slice(1);
  return '+' + info.cc + digits;
}

// Numeric and ISO-like dates read by code. orders: system -> 'MDY' | 'DMY' | 'YMD' (from the notes).
// Dotted day.month.year (LEDGR) is always day-first; Japanese era S/H per KOBO notes.
function parseDate(raw, system, orders, isBirth) {
  if (!raw) return null;
  const s = String(raw).trim();
  let m;
  const iso = (y, mo, d) => {
    if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
    return String(y).padStart(4, '0') + '-' + String(mo).padStart(2, '0') + '-' + String(d).padStart(2, '0');
  };
  const yr = (y) => (y.length === 2 ? (isBirth ? 1900 : 2000) + parseInt(y, 10) : parseInt(y, 10));
  if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/))) return iso(+m[1], +m[2], +m[3]);
  if ((m = s.match(/^(\d{4})[\/.](\d{1,2})[\/.](\d{1,2})$/))) return iso(+m[1], +m[2], +m[3]);
  if ((m = s.match(/^([SH])(\d{1,2})\.(\d{1,2})\.(\d{1,2})$/))) {
    const y = m[1] === 'S' ? 1925 + +m[2] : 1988 + +m[2];
    return iso(y, +m[3], +m[4]);
  }
  if ((m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{2,4})$/))) return iso(yr(m[3]), +m[2], +m[1]);
  if ((m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/))) {
    const order = orders[system];
    if (order === 'MDY') return iso(yr(m[3]), +m[1], +m[2]);
    if (order === 'DMY') return iso(yr(m[3]), +m[2], +m[1]);
    return null;
  }
  return null;
}

function titleIfUpper(s) {
  if (!s || s !== s.toUpperCase()) return s;
  return s.toLowerCase().replace(/(^|[\s\-'])(\p{L})/gu, (m, a, b) => a + b.toUpperCase());
}

// Use the accented spelling of a part that another row of the person writes with accents.
function restore(part, others) {
  if (!part || NONASCII.test(part)) return part;
  const key = strip(part).toLowerCase();
  for (const q of others) {
    if (q && NONASCII.test(q) && variants(q).includes(key)) return q;
  }
  return part;
}

export default function main(input) {
  const spec = String(input.spec || '');
  const orders = {};
  const flips = {};
  for (const c of input.config || []) {
    if (!c || !c.system) continue;
    const sys = String(c.system).toUpperCase();
    if (c.numeric_order) orders[sys] = String(c.numeric_order).toUpperCase();
    if (c.sign_flip === -1 || c.sign_flip === 1) flips[sys] = c.sign_flip;
  }
  const P = parseSpec(spec);
  const debug = { date_orders: orders, sign_flips: flips, parse_errors: [], calling_codes: Object.keys(P.calling).length, rates: Object.keys(P.rates), nicknames: Object.keys(P.nick).length };
  const byId = new Map();
  for (const it of input.results || []) {
    if (!it || !it.rows || !Array.isArray(it.rows.rows)) { debug.parse_errors.push(JSON.stringify(it).slice(0, 300)); continue; }
    for (const r of it.rows.rows) {
      if (r && Number.isInteger(r.row_id) && !byId.has(r.row_id)) byId.set(r.row_id, r);
    }
  }
  const expected = (input.expected_ids || []).filter(x => x !== null);
  debug.missing_rows = expected.filter(id => !byId.has(id));

  const rows = [];
  for (const id of [...byId.keys()].sort((a, b) => a - b)) {
    const r = byId.get(id);
    let country = r.country ? String(r.country).trim().toUpperCase() : null;
    if (country === 'UK') country = 'GB';
    if (country && !/^[A-Z]{2}$/.test(country)) country = null;
    const system = String(r.system || '').toUpperCase();
    let birth = parseDate(r.birth_as_written, system, orders, true) || (r.birth_date && /^\d{4}-\d{2}-\d{2}$/.test(r.birth_date) ? r.birth_date : null);
    if (birth === '1900-01-01') birth = null;
    const phone = normPhone(r.phone_as_written, country || (system === 'KOBO' ? 'JP' : null), system, P.calling);
    const upd = parseDate(r.update_as_written, system, orders, false) || (r.update_date && /^\d{4}-\d{2}-\d{2}$/.test(r.update_date) ? r.update_date : null);
    rows.push({
      row_id: id, system, void: !!r.void, void_reason: r.void_reason || '',
      family: String(r.family_name || '').trim(), given: String(r.given_name || '').trim(),
      birth, country: system === 'KOBO' && !country ? 'JP' : country,
      phone, balance: typeof r.balance === 'number' && isFinite(r.balance) ? r.balance * (system === 'VENDEX' ? 1 : (flips[system] || 1)) : null,
      currency: r.currency ? String(r.currency).toUpperCase() : null,
      update: upd, restamped: r.update_is_real === false,
    });
  }
  const active = rows.filter(r => !r.void);
  debug.voided = rows.filter(r => r.void).map(r => ({ row: r.row_id, why: r.void_reason }));

  const nameOf = (r) => ({ g: formalGiven(r.given, P.nick), f: r.family });
  const same = (a, b) => {
    const na = nameOf(a), nb = nameOf(b);
    return partDist(na.g, nb.g) + partDist(na.f, nb.f) <= 1;
  };
  const linked = (a, b) => {
    if (!same(a, b)) return false;
    if (a.birth && b.birth) return a.birth === b.birth;
    return !!a.phone && a.phone === b.phone;
  };

  // union-find over active rows
  const parent = new Map(active.map(r => [r.row_id, r.row_id]));
  const find = (x) => { while (parent.get(x) !== x) { parent.set(x, parent.get(parent.get(x))); x = parent.get(x); } return x; };
  for (let i = 0; i < active.length; i++) for (let j = i + 1; j < active.length; j++) {
    if (linked(active[i], active[j])) parent.set(find(active[i].row_id), find(active[j].row_id));
  }
  const groups = new Map();
  for (const r of active) {
    const k = find(r.row_id);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(r);
  }

  const records = [];
  for (const g of groups.values()) {
    const sorted = g.slice().sort((a, b) => {
      if (a.restamped !== b.restamped) return a.restamped ? 1 : -1;
      if (a.update !== b.update) {
        if (!a.update) return 1;
        if (!b.update) return -1;
        return a.update < b.update ? 1 : -1;
      }
      return a.row_id - b.row_id;
    });
    const w = sorted[0];
    const gWinner = formalGiven(w.given, P.nick);
    const givenOthers = sorted.map(r => formalGiven(r.given, P.nick));
    const famOthers = sorted.map(r => r.family);
    const given = titleIfUpper(restore(gWinner, givenOthers));
    const family = titleIfUpper(restore(w.family, famOthers));
    const birth = (sorted.find(r => r.birth) || {}).birth || null;
    const country = (sorted.find(r => r.country) || {}).country || null;
    const phone = (sorted.find(r => r.phone) || {}).phone || null;
    let amount = null;
    const bal = sorted.find(r => r.balance !== null && r.currency);
    if (bal) {
      const cur = bal.currency;
      const f = dec(bal.balance);
      if (cur === 'USD') amount = roundCents(f);
      else if (P.rates[cur + '/USD']) amount = roundCents(mul(f, dec(P.rates[cur + '/USD'])));
      else if (P.rates['USD/' + cur]) amount = roundCents(div(f, dec(P.rates['USD/' + cur])));
      else debug.parse_errors.push('no rate for ' + cur);
    }
    const ids = g.map(r => r.row_id).sort((a, b) => a - b);
    records.push({
      entity_id: ids[0], source_rows: ids,
      given_name: given, family_name: family,
      birth_date: birth, country, phone_e164: phone, amount_usd: amount,
    });
  }
  records.sort((a, b) => a.entity_id - b.entity_id);
  return { records, debug, expected_active: active.map(r => r.row_id) };
}

function mul(a, b) { return { n: a.n * b.n, d: a.d * b.d }; }
function div(a, b) { return { n: a.n * b.d, d: a.d * b.n }; }

// Structural checks on the merged master list; records problems, does not change the answer.
export default function main(input) {
  const s = input.subject || {};
  const records = s.records || [];
  const reasons = [];
  const seen = new Set();
  for (const r of records) {
    if (!Array.isArray(r.source_rows) || r.source_rows.length === 0) reasons.push('empty source_rows for ' + r.entity_id);
    if (r.entity_id !== Math.min(...(r.source_rows || [Infinity]))) reasons.push('entity_id not minimal row for ' + r.entity_id);
    for (const id of r.source_rows || []) {
      if (seen.has(id)) reasons.push('row ' + id + ' in two records');
      seen.add(id);
    }
    if (!r.given_name && !r.family_name) reasons.push('no name for ' + r.entity_id);
    if (r.birth_date && !/^\d{4}-\d{2}-\d{2}$/.test(r.birth_date)) reasons.push('bad birth_date for ' + r.entity_id);
    if (r.country && !/^[A-Z]{2}$/.test(r.country)) reasons.push('bad country for ' + r.entity_id);
    if (r.phone_e164 && !/^\+\d+$/.test(r.phone_e164)) reasons.push('bad phone for ' + r.entity_id);
  }
  const missing = (s.expected_active || []).filter(id => !seen.has(id));
  if (missing.length) reasons.push('active rows not in any record: ' + missing.join(','));
  return { pass: reasons.length === 0, score: reasons.length === 0 ? 1 : 0, reasons };
}
